// 由 tools/build_vboard.py 產生，不要手改；來源 vboard/py/
export const PY_FILES = {
 "_vboard.py": "\"\"\"虛擬板執行器（Python 端）：建立 lab.display、執行學生程式、把例外整理成和實機一樣的 traceback。\"\"\"\nimport sys\nimport io\nimport lab\nimport labjs as _js\n\n\ndef setup(board):\n    lab.board = board\n    from lab import board_tqt\n    if board in board_tqt.SIZES:\n        w, h = board_tqt.SIZES[board]\n        lab.display = board_tqt.Display(w, h)\n    else:\n        lab.display = board_tqt.DummyDisplay()\n    lab._stop = False\n    lab._cmd_handler = None\n    del lab._cmd_queue[:]\n    lab._pins.clear()\n\n\ndef check(code, name=\"main.py\"):\n    \"\"\"語法檢查：回 JSON 字串 {\"ok\",\"line\",\"msg\"}，與板子 /check 同格式。\"\"\"\n    import json\n    try:\n        compile(code, name, \"exec\")\n        return json.dumps({\"ok\": True, \"line\": None, \"msg\": \"ok\"})\n    except SyntaxError as e:\n        buf = io.StringIO()\n        sys.print_exception(e, buf)\n        txt = buf.getvalue()\n        line = None\n        for l in txt.split(\"\\n\"):\n            if (\"File \\\"%s\\\"\" % name) in l and \"line \" in l:\n                try:\n                    line = int(l.split(\"line \")[1].split(\",\")[0].split()[0])\n                except Exception:\n                    pass\n        msg = txt.strip().split(\"\\n\")[-1]\n        return json.dumps({\"ok\": False, \"line\": line, \"msg\": msg})\n\n\ndef print_exception(e, name=\"main.py\"):\n    buf = io.StringIO()\n    sys.print_exception(e, buf)\n    lines = []\n    for l in buf.getvalue().split(\"\\n\"):\n        if \"<stdin>\" in l or \"_vboard.py\" in l:\n            continue\n        lines.append(l)\n    return \"\\n\".join(lines).strip() + \"\\n\"\n\n\ndef clear_main(g):\n    \"\"\"清掉上一次執行留下的全域變數（學生程式在 runPython 的全域命名空間執行，由 JS 傳 globals() 進來）。\"\"\"\n    for k in list(g.keys()):\n        if k not in (\"__name__\", \"__builtins__\", \"__file__\", \"_vboard\", \"lab\", \"sys\"):\n            del g[k]\n    g[\"lab\"] = lab\n\n\ndef begin(name=\"main.py\"):\n    import time\n    lab._stop = False\n    lab._last_yield = time.ticks_ms()\n    _js.emit('{\"t\":\"start\",\"file\":\"%s\"}' % name)\n\n\ndef format_error(txt, name=\"main.py\"):\n    \"\"\"把 runPythonAsync 丟出的 traceback 整理成和實機一樣：<stdin> → 檔名，去掉執行器的框架。\"\"\"\n    out = []\n    for l in txt.split(\"\\n\"):\n        if \"_vboard.py\" in l or \"lab/__init__.py\" in l or \"micropython.mjs\" in l or l.strip().startswith(\"at \"):\n            continue\n        out.append(l.replace('\"<stdin>\"', '\"%s\"' % name))\n    return \"\\n\".join(out).strip() + \"\\n\"\n",
 "dht.py": "\"\"\"dht（虛擬板替身）：量測值由模擬器的元件層提供（DHT22 元件的溫濕度滑桿）；沒接元件時回 None 並丟 OSError，和實機沒接一樣。\"\"\"\nimport labjs as _js\n\n\nclass DHTBase:\n    def __init__(self, pin):\n        self.pin = pin if isinstance(pin, int) else pin.id\n        self._t = None\n        self._h = None\n\n    def measure(self):\n        s = _js.sensor_value(self.pin)\n        if s is None:\n            raise OSError(\"DHT 沒有回應（檢查 SDA 腳位、VCC 與 GND）\")\n        import json\n        d = json.loads(s) if isinstance(s, str) else s\n        self._t = d.get(\"temperature\")\n        self._h = d.get(\"humidity\")\n\n    def temperature(self):\n        return self._t\n\n    def humidity(self):\n        return self._h\n\n\nclass DHT11(DHTBase):\n    pass\n\n\nclass DHT22(DHTBase):\n    pass\n",
 "lab/__init__.py": "\"\"\"lab（虛擬板版）：和板子上的 lab 同一組 API，但在瀏覽器的 MicroPython（WebAssembly）裡執行。\n\n差異：lab.sleep 由執行器改寫成 `await lab.sleep(...)`（頂層與含它的函式都會自動變 async），\n畫面、LED、腳位、感測值全部透過 labjs（JS 替身）送到虛擬板畫面。\n\"\"\"\nimport time as _time\nimport json as _json\nimport labjs as _js\n\n__version__ = \"0.5.1-virtual\"\n\n\nclass StopRequested(BaseException):\n    \"\"\"停止鍵按下後，lab.sleep() 會丟出這個例外來結束程式。\n    繼承 BaseException：學生程式的 except Exception 不會把停止鍵吃掉。\"\"\"\n    pass\n\n\n_stop = False\n_cmd_handler = None\n_cmd_queue = []\ndisplay = None            # 由 _vboard.setup() 依板型設定\nboard = \"tqt_pro\"\n_pins = {}\n_last_yield = 0\n_pending = []            # on_cmd 處理函式若含 lab.sleep 會變成 async，回傳的協程排到這裡，在 lab.sleep 裡 await\ncamera = None\n\n\ndef _emit(t, **kw):\n    kw[\"t\"] = t\n    _js.emit(_json.dumps(kw))\n\n\ndef emit(t, **kw):\n    _emit(t, **kw)\n\n\ndef _push_cmd(js_str):\n    \"\"\"JS 送進來的遙控／視覺指令（JSON 字串）先排隊，等學生程式呼叫 lab.sleep／lab.running 時處理。\"\"\"\n    try:\n        cmd = _json.loads(js_str)\n    except Exception:\n        return\n    if cmd.get(\"op\") == \"led\" and not _cmd_handler:\n        led(cmd.get(\"v\")); return\n    _cmd_queue.append(cmd)\n    if len(_cmd_queue) > 50:\n        del _cmd_queue[:25]\n\n\ndef _drain_cmds():\n    while _cmd_queue:\n        cmd = _cmd_queue.pop(0)\n        if cmd.get(\"op\") == \"led\" and cmd.get(\"_builtin\"):\n            led(cmd.get(\"v\")); continue\n        if _cmd_handler:\n            try:\n                r = _cmd_handler(cmd)\n                if r is not None and hasattr(r, \"send\") and hasattr(r, \"close\"):\n                    _pending.append(r)\n            except StopRequested:\n                raise\n            except Exception as e:\n                _emit(\"err\", s=\"on_cmd 處理錯誤：%r\\n\" % e)\n\n\ndef running():\n    \"\"\"停止鍵按下後變 False。虛擬板：迴圈超過 3 秒都沒有 lab.sleep 會自動停（瀏覽器畫面會卡住）。\"\"\"\n    _drain_cmds()\n    if _stop:\n        return False\n    if _time.ticks_diff(_time.ticks_ms(), _last_yield) > 3000:\n        _emit(\"err\", s=\"虛擬板：迴圈裡超過 3 秒沒有 lab.sleep()，畫面會卡住，已自動停止。請在 while lab.running(): 裡加 lab.sleep(0.05)。\\n\")\n        raise StopRequested()\n    return True\n\n\nasync def sleep(seconds):\n    \"\"\"像 time.sleep，但會讓瀏覽器畫面更新，並處理排隊中的指令；停止時丟 StopRequested。\"\"\"\n    global _last_yield\n    _drain_cmds()\n    while _pending:\n        await _pending.pop(0)\n    if _stop:\n        await _js.sleep(0)   # 先讓出再丟：程式用 except: 把停止吃掉又馬上再 sleep 時，瀏覽器才不會整個卡死\n        raise StopRequested()\n    ms = int(seconds * 1000)\n    end = _time.ticks_add(_time.ticks_ms(), ms)\n    while True:\n        left = _time.ticks_diff(end, _time.ticks_ms())\n        await _js.sleep(min(50, max(0, left)))\n        _last_yield = _time.ticks_ms()\n        _drain_cmds()\n        if _stop:\n            raise StopRequested()\n        if left <= 50:\n            break\n\n\nasync def sleep_ms(ms):\n    await sleep(ms / 1000)\n\n\ndef log(*args):\n    s = \" \".join(str(a) for a in args)\n    print(s)\n\n\ndef send(**values):\n    \"\"\"把感測值送到主控台／感測值列：lab.send(temp=25.3)\"\"\"\n    _emit(\"sensor\", v=values)\n\n\ndef on_cmd(fn):\n    global _cmd_handler\n    _cmd_handler = fn\n    return fn\n\n\ndef rssi():\n    \"\"\"虛擬 Wi-Fi 訊號（由虛擬板滑桿設定，預設 -55 dBm）。\"\"\"\n    return _js.rssi()\n\n\ndef battery():\n    \"\"\"虛擬電池電壓（由虛擬板滑桿設定）。\"\"\"\n    if board != \"tqt_pro\":\n        return None\n    return _js.battery()\n\n\ndef pin(n, mode=\"out\"):\n    from machine import Pin\n    key = (n, mode)\n    if key not in _pins:\n        _pins[key] = Pin(n, Pin.OUT if mode == \"out\" else Pin.IN)\n    return _pins[key]\n\n\ndef led(v):\n    \"\"\"板載 LED：T-QT Pro 沒有 LED → 亮螢幕右上角小方塊（和實機一樣）＋虛擬板角落的 LED。\"\"\"\n    _js.led(1 if v else 0)\n    if board in (\"tqt_pro\", \"tdisplay_s3\") and display is not None and hasattr(display, \"buf\"):\n        display.fill_rect(display.width - 8, 0, 8, 8, display.WHITE if v else display.BLACK)\n        display.show()\n",
 "lab/board_tqt.py": "\"\"\"板上彩色螢幕（虛擬板版）：T-QT Pro 128×128、T-Display S3 170×320，同一份 framebuf 畫法，show() 把 RGB565 緩衝交給 JS 畫到 canvas。\"\"\"\nimport framebuf\nimport labjs as _js\n\nW = H = 128                      # 預設 T-QT Pro；Display(w, h) 可指定\nSIZES = {\"tqt_pro\": (128, 128), \"tdisplay_s3\": (170, 320)}\n\n\ndef color(r, g, b):\n    \"\"\"RGB888 → 面板用的 RGB565（已交換位元組，可直接給 framebuf）——與實機完全相同。\"\"\"\n    c = ((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3)\n    return ((c & 0xFF) << 8) | (c >> 8)\n\n\nclass Display(framebuf.FrameBuffer):\n    BLACK = 0\n    WHITE = 0xFFFF\n    RED = color(255, 0, 0)\n    GREEN = color(0, 255, 0)\n    BLUE = color(0, 0, 255)\n    YELLOW = color(255, 255, 0)\n    CYAN = color(0, 255, 255)\n\n    def __init__(self, w=W, h=H):\n        self.width, self.height = w, h\n        self.buf = bytearray(w * h * 2)\n        super().__init__(self.buf, w, h, framebuf.RGB565)\n        self.fill(0)\n        self.show()\n\n    def show(self):\n        f = open(\"/screen.bin\", \"wb\")\n        f.write(self.buf)\n        f.close()\n        _js.show()\n\n    def backlight(self, on=True):\n        pass\n\n    def print_lines(self, lines, fg=0xFFFF, bg=0):\n        self.fill(bg)\n        rows, cols = self.height // 8, self.width // 8\n        for i, line in enumerate(lines[:rows]):\n            self.text(str(line)[:cols], 0, i * 8, fg)\n        self.show()\n\n\nclass DummyDisplay:\n    \"\"\"沒有螢幕的板子：text() 只記錄到主控台（與實機 DummyDisplay 相同）。\"\"\"\n    BLACK = 0; WHITE = 1; RED = 2; GREEN = 3; BLUE = 4; YELLOW = 5; CYAN = 6\n\n    def __init__(self):\n        self.lines = []\n\n    def fill(self, c): self.lines = []\n    def fill_rect(self, *a): pass\n    def pixel(self, *a): pass\n    def rect(self, *a): pass\n    def line(self, *a): pass\n    def hline(self, *a): pass\n    def vline(self, *a): pass\n\n    def text(self, s, x=0, y=0, c=1):\n        self.lines.append(s)\n\n    def show(self):\n        import lab\n        if self.lines:\n            lab.emit(\"display\", lines=self.lines[:])\n\n    def print_lines(self, lines, *a):\n        self.lines = list(lines); self.show()\n\n    def backlight(self, on=True): pass\n",
 "lab/boards.py": "\"\"\"板型表（虛擬板子集）：只有 lab.led 與保護檢查用到的欄位。\"\"\"\nLED_PIN = {\"tqt_pro\": None, \"devkit\": 2, \"generic\": 2, \"xiao_esp32s3\": 21, \"tdisplay_s3\": None}\nLED_INVERTED = {\"tqt_pro\": False, \"devkit\": False, \"generic\": False, \"xiao_esp32s3\": True, \"tdisplay_s3\": False}\nBUTTONS = {\"tqt_pro\": [0, 47], \"devkit\": [0], \"xiao_esp32s3\": [0], \"tdisplay_s3\": [0, 14]}\nHAS_DISPLAY = {\"tqt_pro\": True, \"devkit\": False, \"generic\": False, \"xiao_esp32s3\": False, \"tdisplay_s3\": True}\n",
 "lcd_api.py": "\"\"\"Provides an API for talking to HD44780 compatible character LCDs.\"\"\"\n\nimport time\n\nclass LcdApi:\n    \"\"\"Implements the API for talking with HD44780 compatible character LCDs.\n    This class only knows what commands to send to the LCD, and not how to get\n    them to the LCD.\n\n    It is expected that a derived class will implement the hal_xxx functions.\n    \"\"\"\n\n    # The following constant names were lifted from the avrlib lcd.h\n    # header file, however, I changed the definitions from bit numbers\n    # to bit masks.\n    #\n    # HD44780 LCD controller command set\n\n    LCD_CLR = 0x01              # DB0: clear display\n    LCD_HOME = 0x02             # DB1: return to home position\n\n    LCD_ENTRY_MODE = 0x04       # DB2: set entry mode\n    LCD_ENTRY_INC = 0x02        # --DB1: increment\n    LCD_ENTRY_SHIFT = 0x01      # --DB0: shift\n\n    LCD_ON_CTRL = 0x08          # DB3: turn lcd/cursor on\n    LCD_ON_DISPLAY = 0x04       # --DB2: turn display on\n    LCD_ON_CURSOR = 0x02        # --DB1: turn cursor on\n    LCD_ON_BLINK = 0x01         # --DB0: blinking cursor\n\n    LCD_MOVE = 0x10             # DB4: move cursor/display\n    LCD_MOVE_DISP = 0x08        # --DB3: move display (0-> move cursor)\n    LCD_MOVE_RIGHT = 0x04       # --DB2: move right (0-> left)\n\n    LCD_FUNCTION = 0x20         # DB5: function set\n    LCD_FUNCTION_8BIT = 0x10    # --DB4: set 8BIT mode (0->4BIT mode)\n    LCD_FUNCTION_2LINES = 0x08  # --DB3: two lines (0->one line)\n    LCD_FUNCTION_10DOTS = 0x04  # --DB2: 5x10 font (0->5x7 font)\n    LCD_FUNCTION_RESET = 0x30   # See \"Initializing by Instruction\" section\n\n    LCD_CGRAM = 0x40            # DB6: set CG RAM address\n    LCD_DDRAM = 0x80            # DB7: set DD RAM address\n\n    LCD_RS_CMD = 0\n    LCD_RS_DATA = 1\n\n    LCD_RW_WRITE = 0\n    LCD_RW_READ = 1\n\n    def __init__(self, num_lines, num_columns):\n        self.num_lines = num_lines\n        if self.num_lines > 4:\n            self.num_lines = 4\n        self.num_columns = num_columns\n        if self.num_columns > 40:\n            self.num_columns = 40\n        self.cursor_x = 0\n        self.cursor_y = 0\n        self.implied_newline = False\n        self.backlight = True\n        self.display_off()\n        self.backlight_on()\n        self.clear()\n        self.hal_write_command(self.LCD_ENTRY_MODE | self.LCD_ENTRY_INC)\n        self.hide_cursor()\n        self.display_on()\n\n    def clear(self):\n        \"\"\"Clears the LCD display and moves the cursor to the top left\n        corner.\n        \"\"\"\n        self.hal_write_command(self.LCD_CLR)\n        self.hal_write_command(self.LCD_HOME)\n        self.cursor_x = 0\n        self.cursor_y = 0\n\n    def show_cursor(self):\n        \"\"\"Causes the cursor to be made visible.\"\"\"\n        self.hal_write_command(self.LCD_ON_CTRL | self.LCD_ON_DISPLAY |\n                               self.LCD_ON_CURSOR)\n\n    def hide_cursor(self):\n        \"\"\"Causes the cursor to be hidden.\"\"\"\n        self.hal_write_command(self.LCD_ON_CTRL | self.LCD_ON_DISPLAY)\n\n    def blink_cursor_on(self):\n        \"\"\"Turns on the cursor, and makes it blink.\"\"\"\n        self.hal_write_command(self.LCD_ON_CTRL | self.LCD_ON_DISPLAY |\n                               self.LCD_ON_CURSOR | self.LCD_ON_BLINK)\n\n    def blink_cursor_off(self):\n        \"\"\"Turns on the cursor, and makes it no blink (i.e. be solid).\"\"\"\n        self.hal_write_command(self.LCD_ON_CTRL | self.LCD_ON_DISPLAY |\n                               self.LCD_ON_CURSOR)\n\n    def display_on(self):\n        \"\"\"Turns on (i.e. unblanks) the LCD.\"\"\"\n        self.hal_write_command(self.LCD_ON_CTRL | self.LCD_ON_DISPLAY)\n\n    def display_off(self):\n        \"\"\"Turns off (i.e. blanks) the LCD.\"\"\"\n        self.hal_write_command(self.LCD_ON_CTRL)\n\n    def backlight_on(self):\n        \"\"\"Turns the backlight on.\n\n        This isn't really an LCD command, but some modules have backlight\n        controls, so this allows the hal to pass through the command.\n        \"\"\"\n        self.backlight = True\n        self.hal_backlight_on()\n\n    def backlight_off(self):\n        \"\"\"Turns the backlight off.\n\n        This isn't really an LCD command, but some modules have backlight\n        controls, so this allows the hal to pass through the command.\n        \"\"\"\n        self.backlight = False\n        self.hal_backlight_off()\n\n    def move_to(self, cursor_x, cursor_y):\n        \"\"\"Moves the cursor position to the indicated position. The cursor\n        position is zero based (i.e. cursor_x == 0 indicates first column).\n        \"\"\"\n        self.cursor_x = cursor_x\n        self.cursor_y = cursor_y\n        addr = cursor_x & 0x3f\n        if cursor_y & 1:\n            addr += 0x40    # Lines 1 & 3 add 0x40\n        if cursor_y & 2:    # Lines 2 & 3 add number of columns\n            addr += self.num_columns\n        self.hal_write_command(self.LCD_DDRAM | addr)\n\n    def putchar(self, char):\n        \"\"\"Writes the indicated character to the LCD at the current cursor\n        position, and advances the cursor by one position.\n        \"\"\"\n        if char == '\\n':\n            if self.implied_newline:\n                # self.implied_newline means we advanced due to a wraparound,\n                # so if we get a newline right after that we ignore it.\n                self.implied_newline = False\n            else:\n                self.cursor_x = self.num_columns\n        else:\n            self.hal_write_data(ord(char))\n            self.cursor_x += 1\n        if self.cursor_x >= self.num_columns:\n            self.cursor_x = 0\n            self.cursor_y += 1\n            self.implied_newline = (char != '\\n')\n        if self.cursor_y >= self.num_lines:\n            self.cursor_y = 0\n        self.move_to(self.cursor_x, self.cursor_y)\n\n    def putstr(self, string):\n        \"\"\"Write the indicated string to the LCD at the current cursor\n        position and advances the cursor position appropriately.\n        \"\"\"\n        for char in string:\n            self.putchar(char)\n\n    def custom_char(self, location, charmap):\n        \"\"\"Write a character to one of the 8 CGRAM locations, available\n        as chr(0) through chr(7).\n        \"\"\"\n        location &= 0x7\n        self.hal_write_command(self.LCD_CGRAM | (location << 3))\n        self.hal_sleep_us(40)\n        for i in range(8):\n            self.hal_write_data(charmap[i])\n            self.hal_sleep_us(40)\n        self.move_to(self.cursor_x, self.cursor_y)\n\n    def hal_backlight_on(self):\n        \"\"\"Allows the hal layer to turn the backlight on.\n\n        If desired, a derived HAL class will implement this function.\n        \"\"\"\n        pass\n\n    def hal_backlight_off(self):\n        \"\"\"Allows the hal layer to turn the backlight off.\n\n        If desired, a derived HAL class will implement this function.\n        \"\"\"\n        pass\n\n    def hal_write_command(self, cmd):\n        \"\"\"Write a command to the LCD.\n\n        It is expected that a derived HAL class will implement this\n        function.\n        \"\"\"\n        raise NotImplementedError\n\n    def hal_write_data(self, data):\n        \"\"\"Write data to the LCD.\n\n        It is expected that a derived HAL class will implement this\n        function.\n        \"\"\"\n        raise NotImplementedError\n\n    # This is a default implementation of hal_sleep_us which is suitable\n    # for most micropython implementations. For platforms which don't\n    # support `time.sleep_us()` they should provide their own implementation\n    # of hal_sleep_us in their hal layer and it will be used instead.\n    def hal_sleep_us(self, usecs):\n        \"\"\"Sleep for some time (given in microseconds).\"\"\"\n        time.sleep_us(usecs)  # NOTE this is not part of Standard Python library, specific hal layers will need to override this\n",
 "machine.py": "\"\"\"machine（虛擬板替身）：Pin／PWM／ADC 的狀態都交給 JS 畫在板子上；reset 重開虛擬板。\"\"\"\nimport labjs as _js\n\n\nclass Pin:\n    IN = 0\n    OUT = 1\n    OPEN_DRAIN = 2\n    PULL_UP = 1\n    PULL_DOWN = 2\n    IRQ_RISING = 1\n    IRQ_FALLING = 2\n\n    def __init__(self, id, mode=-1, pull=-1, value=None, **kw):\n        self.id = int(id)\n        self.mode = mode\n        self.pull = pull\n        self._v = 0\n        if value is not None:\n            self.value(value)\n        _js.pin_mode(self.id, \"out\" if mode == Pin.OUT else \"in\", 1 if pull == Pin.PULL_UP else 0)\n\n    def init(self, mode=-1, pull=-1, **kw):\n        self.mode = mode; self.pull = pull\n\n    def value(self, v=None):\n        if v is None:\n            if self.mode == Pin.OUT:\n                return self._v\n            return int(_js.pin_read(self.id))\n        self._v = 1 if v else 0\n        _js.pin_write(self.id, self._v)\n\n    def on(self): self.value(1)\n    def off(self): self.value(0)\n    def __call__(self, v=None): return self.value(v)\n\n    def irq(self, handler=None, trigger=3, **kw):\n        _js.pin_irq(self.id, handler, trigger)\n        return self\n\n\nclass PWM:\n    def __init__(self, pin, freq=5000, duty=None, duty_u16=None, duty_ns=None, **kw):\n        self.pin = pin if isinstance(pin, int) else pin.id\n        self._freq = freq\n        self._duty16 = 0\n        if duty is not None: self.duty(duty)\n        if duty_u16 is not None: self.duty_u16(duty_u16)\n        if duty_ns is not None: self.duty_ns(duty_ns)\n\n    def freq(self, f=None):\n        if f is None: return self._freq\n        self._freq = f; self._report()\n\n    def duty(self, d=None):\n        if d is None: return self._duty16 * 1023 // 65535\n        self._duty16 = int(d) * 65535 // 1023; self._report()\n\n    def duty_u16(self, d=None):\n        if d is None: return self._duty16\n        self._duty16 = int(d); self._report()\n\n    def duty_ns(self, ns=None):\n        period_ns = 1_000_000_000 // max(1, self._freq)\n        if ns is None: return self._duty16 * period_ns // 65535\n        self._duty16 = int(ns) * 65535 // period_ns; self._report()\n\n    def deinit(self):\n        _js.pwm(self.pin, 0, 0)\n\n    def _report(self):\n        _js.pwm(self.pin, self._freq, self._duty16)\n\n\nclass ADC:\n    ATTN_0DB = 0; ATTN_2_5DB = 1; ATTN_6DB = 2; ATTN_11DB = 3\n    WIDTH_12BIT = 12\n\n    def __init__(self, pin, atten=3, **kw):\n        self.pin = pin if isinstance(pin, int) else pin.id\n        _js.adc_init(self.pin)\n\n    def atten(self, a): pass\n    def width(self, w): pass\n\n    def read(self):\n        return int(_js.adc_read(self.pin))\n\n    def read_u16(self):\n        return int(_js.adc_read(self.pin)) * 65535 // 4095\n\n    def read_uv(self):\n        return int(_js.adc_read(self.pin)) * 3300000 // 4095\n\n\nclass RTC:\n    def datetime(self, *a):\n        import time\n        t = time.localtime()\n        return (t[0], t[1], t[2], t[6], t[3], t[4], t[5], 0)\n\n\ndef reset():\n    _js.reset()\n    raise SystemExit()\n\n\ndef soft_reset():\n    reset()\n\n\ndef freq(*a):\n    return 240_000_000\n\n\ndef unique_id():\n    return b\"\\x24\\xec\\x4a\\x00\\x7f\\x2a\"\n\n\ndef idle(): pass\n\n\nclass WDT:\n    def __init__(self, *a, **k): pass\n    def feed(self): pass\n\n\ndef time_pulse_us(pin, level, timeout_us=1000000):\n    \"\"\"量脈衝寬度：虛擬板由元件層（HC-SR04 等）直接回答微秒數；沒有元件回 -2（逾時），與實機相同。\"\"\"\n    p = pin if isinstance(pin, int) else pin.id\n    v = _js.pulse_us(p, 1 if level else 0)\n    return int(v) if v is not None else -2\n\n\nclass I2C:\n    \"\"\"I2C 替身：每筆交易發 i2c 事件給元件層（SSD1306、LCD1602 解碼器）。\"\"\"\n    def __init__(self, id=0, scl=None, sda=None, freq=400000, **kw):\n        self.id = id\n        self.scl = scl.id if hasattr(scl, \"id\") else scl\n        self.sda = sda.id if hasattr(sda, \"id\") else sda\n        _js.i2c_init(self.id, self.scl if self.scl is not None else -1, self.sda if self.sda is not None else -1)\n\n    def scan(self):\n        import json\n        return list(json.loads(_js.i2c_scan(self.id)))\n\n    def _w(self, addr, buf, stop=True):\n        f = open(\"/i2c.bin\", \"wb\"); f.write(bytes(buf)); f.close()\n        ok = _js.i2c_write(self.id, int(addr), len(buf))\n        if not ok:\n            raise OSError(19, \"ENODEV（I2C 位址 0x%02x 沒有裝置回應）\" % addr)\n        return len(buf)\n\n    def writeto(self, addr, buf, stop=True):\n        return self._w(addr, buf, stop)\n\n    def writevto(self, addr, vec, stop=True):\n        return self._w(addr, b\"\".join(bytes(v) for v in vec), stop)\n\n    def writeto_mem(self, addr, memaddr, buf, addrsize=8):\n        return self._w(addr, bytes([memaddr & 0xFF]) + bytes(buf))\n\n    def readfrom(self, addr, nbytes, stop=True):\n        n = _js.i2c_read(self.id, int(addr), int(nbytes))\n        if n is None or n < 0:\n            raise OSError(19, \"ENODEV\")\n        f = open(\"/i2c.bin\", \"rb\"); d = f.read(); f.close()\n        return d[:nbytes]\n\n    def readfrom_into(self, addr, buf, stop=True):\n        d = self.readfrom(addr, len(buf)); buf[:len(d)] = d\n\n    def readfrom_mem(self, addr, memaddr, nbytes, addrsize=8):\n        self._w(addr, bytes([memaddr & 0xFF]))\n        return self.readfrom(addr, nbytes)\n\n    def readfrom_mem_into(self, addr, memaddr, buf, addrsize=8):\n        d = self.readfrom_mem(addr, memaddr, len(buf)); buf[:len(d)] = d\n\n    def start(self): pass\n    def stop(self): pass\n\n\nclass SoftI2C(I2C):\n    pass\n\n\nclass SPI:\n    \"\"\"SPI 替身：write() 把位元組交給元件層（spi 事件）；沒有元件就只是丟掉。\"\"\"\n    MSB = 0; LSB = 1\n    def __init__(self, id=1, baudrate=1000000, polarity=0, phase=0, sck=None, mosi=None, miso=None, **kw):\n        self.id = id\n        self.sck = sck.id if hasattr(sck, \"id\") else sck\n        self.mosi = mosi.id if hasattr(mosi, \"id\") else mosi\n\n    def init(self, **kw): pass\n    def deinit(self): pass\n\n    def write(self, buf):\n        f = open(\"/spi.bin\", \"wb\"); f.write(bytes(buf)); f.close()\n        _js.spi_write(self.id, len(buf))\n\n    def read(self, n, write=0x00):\n        return bytes(n)\n\n    def readinto(self, buf, write=0x00): pass\n\n    def write_readinto(self, wbuf, rbuf):\n        self.write(wbuf)\n\n\nclass SoftSPI(SPI):\n    pass\n",
 "machine_i2c_lcd.py": "\"\"\"Implements a HD44780 character LCD connected via PCF8574 on I2C.\n   This was tested with: https://www.wemos.cc/product/d1-mini.html\"\"\"\n\nfrom lcd_api import LcdApi\nfrom time import sleep_ms\n\n# The PCF8574 has a jumper selectable address: 0x20 - 0x27\nDEFAULT_I2C_ADDR = 0x27\n\n# Defines shifts or masks for the various LCD line attached to the PCF8574\n\nMASK_RS = 0x01\nMASK_RW = 0x02\nMASK_E = 0x04\nSHIFT_BACKLIGHT = 3\nSHIFT_DATA = 4\n\n\nclass I2cLcd(LcdApi):\n    \"\"\"Implements a HD44780 character LCD connected via PCF8574 on I2C.\"\"\"\n\n    def __init__(self, i2c, i2c_addr, num_lines, num_columns):\n        self.i2c = i2c\n        self.i2c_addr = i2c_addr\n        self.i2c.writeto(self.i2c_addr, bytearray([0]))\n        sleep_ms(20)   # Allow LCD time to powerup\n        # Send reset 3 times\n        self.hal_write_init_nibble(self.LCD_FUNCTION_RESET)\n        sleep_ms(5)    # need to delay at least 4.1 msec\n        self.hal_write_init_nibble(self.LCD_FUNCTION_RESET)\n        sleep_ms(1)\n        self.hal_write_init_nibble(self.LCD_FUNCTION_RESET)\n        sleep_ms(1)\n        # Put LCD into 4 bit mode\n        self.hal_write_init_nibble(self.LCD_FUNCTION)\n        sleep_ms(1)\n        LcdApi.__init__(self, num_lines, num_columns)\n        cmd = self.LCD_FUNCTION\n        if num_lines > 1:\n            cmd |= self.LCD_FUNCTION_2LINES\n        self.hal_write_command(cmd)\n\n    def hal_write_init_nibble(self, nibble):\n        \"\"\"Writes an initialization nibble to the LCD.\n\n        This particular function is only used during initialization.\n        \"\"\"\n        byte = ((nibble >> 4) & 0x0f) << SHIFT_DATA\n        self.i2c.writeto(self.i2c_addr, bytearray([byte | MASK_E]))\n        self.i2c.writeto(self.i2c_addr, bytearray([byte]))\n\n    def hal_backlight_on(self):\n        \"\"\"Allows the hal layer to turn the backlight on.\"\"\"\n        self.i2c.writeto(self.i2c_addr, bytearray([1 << SHIFT_BACKLIGHT]))\n\n    def hal_backlight_off(self):\n        \"\"\"Allows the hal layer to turn the backlight off.\"\"\"\n        self.i2c.writeto(self.i2c_addr, bytearray([0]))\n\n    def hal_write_command(self, cmd):\n        \"\"\"Writes a command to the LCD.\n\n        Data is latched on the falling edge of E.\n        \"\"\"\n        byte = ((self.backlight << SHIFT_BACKLIGHT) | (((cmd >> 4) & 0x0f) << SHIFT_DATA))\n        self.i2c.writeto(self.i2c_addr, bytearray([byte | MASK_E]))\n        self.i2c.writeto(self.i2c_addr, bytearray([byte]))\n        byte = ((self.backlight << SHIFT_BACKLIGHT) | ((cmd & 0x0f) << SHIFT_DATA))\n        self.i2c.writeto(self.i2c_addr, bytearray([byte | MASK_E]))\n        self.i2c.writeto(self.i2c_addr, bytearray([byte]))\n        if cmd <= 3:\n            # The home and clear commands require a worst case delay of 4.1 msec\n            sleep_ms(5)\n\n    def hal_write_data(self, data):\n        \"\"\"Write data to the LCD.\"\"\"\n        byte = (MASK_RS | (self.backlight << SHIFT_BACKLIGHT) | (((data >> 4) & 0x0f) << SHIFT_DATA))\n        self.i2c.writeto(self.i2c_addr, bytearray([byte | MASK_E]))\n        self.i2c.writeto(self.i2c_addr, bytearray([byte]))\n        byte = (MASK_RS | (self.backlight << SHIFT_BACKLIGHT) | ((data & 0x0f) << SHIFT_DATA))\n        self.i2c.writeto(self.i2c_addr, bytearray([byte | MASK_E]))\n        self.i2c.writeto(self.i2c_addr, bytearray([byte]))\n",
 "neopixel.py": "\"\"\"neopixel（虛擬板替身）：write() 把每顆 GRB 24 位元的位元流交給 JS（rmt 事件），元件層畫燈。\"\"\"\nimport labjs as _js\n\n\nclass NeoPixel:\n    ORDER = (1, 0, 2, 3)\n\n    def __init__(self, pin, n, bpp=3, timing=1):\n        self.pin = pin if isinstance(pin, int) else pin.id\n        self.n = n\n        self.bpp = bpp\n        self.buf = bytearray(n * bpp)\n\n    def __len__(self):\n        return self.n\n\n    def __setitem__(self, i, v):\n        o = i * self.bpp\n        self.buf[o] = v[1]; self.buf[o + 1] = v[0]; self.buf[o + 2] = v[2]   # GRB\n        if self.bpp == 4:\n            self.buf[o + 3] = v[3]\n\n    def __getitem__(self, i):\n        o = i * self.bpp\n        return (self.buf[o + 1], self.buf[o], self.buf[o + 2]) if self.bpp == 3 else (self.buf[o + 1], self.buf[o], self.buf[o + 2], self.buf[o + 3])\n\n    def fill(self, v):\n        for i in range(self.n):\n            self[i] = v\n\n    def write(self):\n        f = open(\"/rmt.bin\", \"wb\")\n        f.write(self.buf)\n        f.close()\n        _js.rmt(self.pin, self.n, self.bpp)\n",
 "network.py": "\"\"\"network（虛擬板替身）：永遠「已連上」一個假的 Wi-Fi，訊號強度由虛擬板滑桿決定；不能真的連網。\"\"\"\nimport labjs as _js\n\nSTA_IF = 0\nAP_IF = 1\nSTAT_GOT_IP = 1010\n\n\nclass WLAN:\n    def __init__(self, mode=STA_IF):\n        self.mode = mode\n        self._active = True\n\n    def active(self, v=None):\n        if v is None: return self._active\n        self._active = bool(v)\n\n    def isconnected(self):\n        return self.mode == STA_IF\n\n    def connect(self, *a, **k):\n        pass\n\n    def disconnect(self):\n        pass\n\n    def status(self, key=None):\n        if key == \"rssi\":\n            return int(_js.rssi())\n        return STAT_GOT_IP\n\n    def ifconfig(self, *a):\n        return (\"192.168.4.2\", \"255.255.255.0\", \"192.168.4.1\", \"192.168.4.1\")\n\n    def config(self, key=None, **kw):\n        if key == \"essid\" or key == \"ssid\": return \"虛擬板\"\n        if key == \"mac\": return b\"\\x24\\xec\\x4a\\x00\\x7f\\x2a\"\n        return None\n\n    def scan(self):\n        return [(b\"ESP32LAB-virtual\", b\"\\x24\\xec\\x4a\\x00\\x7f\\x2a\", 6, int(_js.rssi()), 3, False)]\n\n\ndef hostname(name=None):\n    return \"esp32lab-virtual\"\n",
 "ntptime.py": "\"\"\"ntptime（虛擬板替身）：瀏覽器的時間就是對的，settime() 什麼都不用做。\"\"\"\nhost = \"pool.ntp.org\"\ntimeout = 1\n\n\ndef time():\n    import time as _t\n    return int(_t.time())\n\n\ndef settime():\n    pass\n",
 "ssd1306.py": "# MicroPython SSD1306 OLED driver, I2C and SPI interfaces\n\nfrom micropython import const\nimport framebuf\n\n\n# register definitions\nSET_CONTRAST = const(0x81)\nSET_ENTIRE_ON = const(0xA4)\nSET_NORM_INV = const(0xA6)\nSET_DISP = const(0xAE)\nSET_MEM_ADDR = const(0x20)\nSET_COL_ADDR = const(0x21)\nSET_PAGE_ADDR = const(0x22)\nSET_DISP_START_LINE = const(0x40)\nSET_SEG_REMAP = const(0xA0)\nSET_MUX_RATIO = const(0xA8)\nSET_IREF_SELECT = const(0xAD)\nSET_COM_OUT_DIR = const(0xC0)\nSET_DISP_OFFSET = const(0xD3)\nSET_COM_PIN_CFG = const(0xDA)\nSET_DISP_CLK_DIV = const(0xD5)\nSET_PRECHARGE = const(0xD9)\nSET_VCOM_DESEL = const(0xDB)\nSET_CHARGE_PUMP = const(0x8D)\n\n\n# Subclassing FrameBuffer provides support for graphics primitives\n# http://docs.micropython.org/en/latest/pyboard/library/framebuf.html\nclass SSD1306(framebuf.FrameBuffer):\n    def __init__(self, width, height, external_vcc):\n        self.width = width\n        self.height = height\n        self.external_vcc = external_vcc\n        self.pages = self.height // 8\n        self.buffer = bytearray(self.pages * self.width)\n        super().__init__(self.buffer, self.width, self.height, framebuf.MONO_VLSB)\n        self.init_display()\n\n    def init_display(self):\n        for cmd in (\n            SET_DISP,  # display off\n            # address setting\n            SET_MEM_ADDR,\n            0x00,  # horizontal\n            # resolution and layout\n            SET_DISP_START_LINE,  # start at line 0\n            SET_SEG_REMAP | 0x01,  # column addr 127 mapped to SEG0\n            SET_MUX_RATIO,\n            self.height - 1,\n            SET_COM_OUT_DIR | 0x08,  # scan from COM[N] to COM0\n            SET_DISP_OFFSET,\n            0x00,\n            SET_COM_PIN_CFG,\n            0x02 if self.width > 2 * self.height else 0x12,\n            # timing and driving scheme\n            SET_DISP_CLK_DIV,\n            0x80,\n            SET_PRECHARGE,\n            0x22 if self.external_vcc else 0xF1,\n            SET_VCOM_DESEL,\n            0x30,  # 0.83*Vcc\n            # display\n            SET_CONTRAST,\n            0xFF,  # maximum\n            SET_ENTIRE_ON,  # output follows RAM contents\n            SET_NORM_INV,  # not inverted\n            SET_IREF_SELECT,\n            0x30,  # enable internal IREF during display on\n            # charge pump\n            SET_CHARGE_PUMP,\n            0x10 if self.external_vcc else 0x14,\n            SET_DISP | 0x01,  # display on\n        ):  # on\n            self.write_cmd(cmd)\n        self.fill(0)\n        self.show()\n\n    def poweroff(self):\n        self.write_cmd(SET_DISP)\n\n    def poweron(self):\n        self.write_cmd(SET_DISP | 0x01)\n\n    def contrast(self, contrast):\n        self.write_cmd(SET_CONTRAST)\n        self.write_cmd(contrast)\n\n    def invert(self, invert):\n        self.write_cmd(SET_NORM_INV | (invert & 1))\n\n    def rotate(self, rotate):\n        self.write_cmd(SET_COM_OUT_DIR | ((rotate & 1) << 3))\n        self.write_cmd(SET_SEG_REMAP | (rotate & 1))\n\n    def show(self):\n        x0 = 0\n        x1 = self.width - 1\n        if self.width != 128:\n            # narrow displays use centred columns\n            col_offset = (128 - self.width) // 2\n            x0 += col_offset\n            x1 += col_offset\n        self.write_cmd(SET_COL_ADDR)\n        self.write_cmd(x0)\n        self.write_cmd(x1)\n        self.write_cmd(SET_PAGE_ADDR)\n        self.write_cmd(0)\n        self.write_cmd(self.pages - 1)\n        self.write_data(self.buffer)\n\n\nclass SSD1306_I2C(SSD1306):\n    def __init__(self, width, height, i2c, addr=0x3C, external_vcc=False):\n        self.i2c = i2c\n        self.addr = addr\n        self.temp = bytearray(2)\n        self.write_list = [b\"\\x40\", None]  # Co=0, D/C#=1\n        super().__init__(width, height, external_vcc)\n\n    def write_cmd(self, cmd):\n        self.temp[0] = 0x80  # Co=1, D/C#=0\n        self.temp[1] = cmd\n        self.i2c.writeto(self.addr, self.temp)\n\n    def write_data(self, buf):\n        self.write_list[1] = buf\n        self.i2c.writevto(self.addr, self.write_list)\n\n\nclass SSD1306_SPI(SSD1306):\n    def __init__(self, width, height, spi, dc, res, cs, external_vcc=False):\n        self.rate = 10 * 1024 * 1024\n        dc.init(dc.OUT, value=0)\n        res.init(res.OUT, value=0)\n        cs.init(cs.OUT, value=1)\n        self.spi = spi\n        self.dc = dc\n        self.res = res\n        self.cs = cs\n        import time\n\n        self.res(1)\n        time.sleep_ms(1)\n        self.res(0)\n        time.sleep_ms(10)\n        self.res(1)\n        super().__init__(width, height, external_vcc)\n\n    def write_cmd(self, cmd):\n        self.spi.init(baudrate=self.rate, polarity=0, phase=0)\n        self.cs(1)\n        self.dc(0)\n        self.cs(0)\n        self.spi.write(bytearray([cmd]))\n        self.cs(1)\n\n    def write_data(self, buf):\n        self.spi.init(baudrate=self.rate, polarity=0, phase=0)\n        self.cs(1)\n        self.dc(1)\n        self.cs(0)\n        self.spi.write(buf)\n        self.cs(1)\n"
};
